#!/usr/bin/env bats
# test_scripts.bats - BATS test suite for defensive Bash scripts
# Run with: bats test/test_scripts.bats

# Setup function runs before each test
setup() {
    # Create temporary test directory
    TEST_TEMP_DIR="$(mktemp -d)"

    # Source common utilities for testing
    source "${BATS_TEST_DIRNAME}/common_utils.sh"
}

# Teardown function runs after each test
teardown() {
    # Clean up temporary directory
    if [[ -n "${TEST_TEMP_DIR:-}" && -d "$TEST_TEMP_DIR" ]]; then
        rm -rf "$TEST_TEMP_DIR"
    fi
}

# Tests for common_utils.sh

@test "log_info outputs to stderr with INFO prefix" {
    run log_info "test message"
    [[ "$output" =~ INFO.*test\ message ]]
}

@test "log_error outputs to stderr with ERROR prefix" {
    run log_error "error message"
    [[ "$output" =~ ERROR.*error\ message ]]
}

@test "check_command succeeds for existing command" {
    run check_command "bash"
    [ "$status" -eq 0 ]
}

@test "check_command fails for non-existent command" {
    run check_command "nonexistent_command_xyz"
    [ "$status" -eq 1 ]
}

@test "validate_file succeeds for existing readable file" {
    local test_file="${TEST_TEMP_DIR}/test.txt"
    echo "test content" > "$test_file"

    run validate_file "$test_file"
    [ "$status" -eq 0 ]
}

@test "validate_file fails for non-existent file" {
    run validate_file "${TEST_TEMP_DIR}/nonexistent.txt"
    [ "$status" -eq 1 ]
}

@test "validate_directory succeeds for existing directory" {
    run validate_directory "$TEST_TEMP_DIR"
    [ "$status" -eq 0 ]
}

@test "validate_directory fails for non-existent directory" {
    run validate_directory "${TEST_TEMP_DIR}/nonexistent"
    [ "$status" -eq 1 ]
}

@test "ensure_directory creates missing directory" {
    local new_dir="${TEST_TEMP_DIR}/new_directory"

    run ensure_directory "$new_dir"
    [ "$status" -eq 0 ]
    [ -d "$new_dir" ]
}

@test "ensure_directory succeeds for existing directory" {
    run ensure_directory "$TEST_TEMP_DIR"
    [ "$status" -eq 0 ]
}

@test "safe_move succeeds for valid source and destination" {
    local source="${TEST_TEMP_DIR}/source.txt"
    local dest="${TEST_TEMP_DIR}/dest.txt"
    echo "content" > "$source"

    run safe_move "$source" "$dest"
    [ "$status" -eq 0 ]
    [ ! -e "$source" ]
    [ -e "$dest" ]
}

@test "safe_move fails when source does not exist" {
    run safe_move "${TEST_TEMP_DIR}/nonexistent" "${TEST_TEMP_DIR}/dest"
    [ "$status" -eq 1 ]
}

@test "safe_move fails when destination already exists" {
    local source="${TEST_TEMP_DIR}/source.txt"
    local dest="${TEST_TEMP_DIR}/dest.txt"
    echo "content" > "$source"
    echo "content" > "$dest"

    run safe_move "$source" "$dest"
    [ "$status" -eq 1 ]
}

@test "check_dependencies succeeds when all commands exist" {
    run check_dependencies "bash" "cat" "ls"
    [ "$status" -eq 0 ]
}

@test "check_dependencies fails when a command is missing" {
    run check_dependencies "bash" "nonexistent_cmd_xyz"
    [ "$status" -eq 1 ]
}

# Tests for safe_backup.sh

@test "safe_backup.sh shows help with --help flag" {
    run "${BATS_TEST_DIRNAME}/safe_backup.sh" --help
    [ "$status" -eq 0 ]
    [[ "$output" =~ Usage ]]
}

@test "safe_backup.sh fails without arguments" {
    run "${BATS_TEST_DIRNAME}/safe_backup.sh"
    [ "$status" -eq 1 ]
}

@test "safe_backup.sh dry-run mode works" {
    local source="${TEST_TEMP_DIR}/source"
    local dest="${TEST_TEMP_DIR}/dest"
    mkdir -p "$source"
    mkdir -p "$dest"
    echo "test" > "${source}/file.txt"

    run "${BATS_TEST_DIRNAME}/safe_backup.sh" --dry-run "$source" "$dest"
    [ "$status" -eq 0 ]
    [[ "$output" =~ "DRY RUN" ]]
}

@test "safe_backup.sh performs directory backup" {
    local source="${TEST_TEMP_DIR}/source"
    local dest="${TEST_TEMP_DIR}/dest"
    mkdir -p "$source"
    mkdir -p "$dest"
    echo "test content" > "${source}/file.txt"

    run "${BATS_TEST_DIRNAME}/safe_backup.sh" "$source" "$dest"
    [ "$status" -eq 0 ]

    # Verify backup was created with timestamp pattern
    local backup_count
    backup_count=$(find "$dest" -maxdepth 1 -type d -name "source_*" | wc -l)
    [ "$backup_count" -ge 1 ]
}

@test "safe_backup.sh fails when source does not exist" {
    local dest="${TEST_TEMP_DIR}/dest"
    mkdir -p "$dest"

    run "${BATS_TEST_DIRNAME}/safe_backup.sh" "${TEST_TEMP_DIR}/nonexistent" "$dest"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh creates destination if it does not exist" {
    local source="${TEST_TEMP_DIR}/source"
    local dest="${TEST_TEMP_DIR}/new_dest"
    mkdir -p "$source"
    echo "test" > "${source}/file.txt"

    run "${BATS_TEST_DIRNAME}/safe_backup.sh" "$source" "$dest"
    [ "$status" -eq 0 ]
    [ -d "$dest" ]
}

@test "safe_backup.sh prevents backup to subdirectory of source" {
    local source="${TEST_TEMP_DIR}/source"
    local dest="${source}/backup"
    mkdir -p "$source"

    run "${BATS_TEST_DIRNAME}/safe_backup.sh" "$source" "$dest"
    [ "$status" -eq 2 ]
}

@test "safe_backup.sh compressed mode creates tar.gz archive" {
    skip "Requires tar and gzip"

    local source="${TEST_TEMP_DIR}/source"
    local dest="${TEST_TEMP_DIR}/dest"
    mkdir -p "$source"
    mkdir -p "$dest"
    echo "test content" > "${source}/file.txt"

    run "${BATS_TEST_DIRNAME}/safe_backup.sh" --compress "$source" "$dest"
    [ "$status" -eq 0 ]

    # Verify tar.gz archive was created
    local archive_count
    archive_count=$(find "$dest" -maxdepth 1 -type f -name "source_*.tar.gz" | wc -l)
    [ "$archive_count" -ge 1 ]
}

